import type { ReactNode, SVGProps } from 'react';

/**
 * Custom medical icon set — filled silhouette style.
 *
 * Shared spec: 48x48 viewBox, fill=currentColor, filled silhouettes — a few
 * icons add currentColor strokes on top for vessels or bonds. Kept at 48 units
 * (rather than rescaled to 24) so the Healthicons-derived paths below can be
 * used verbatim, with zero risk of a coordinate-scaling transcription error.
 *
 * Organ/anatomy icons marked HEALTHICONS are adapted from the Healthicons
 * project (healthicons.org, CC0 — no attribution required), trimmed to the
 * single element needed and reused verbatim otherwise. The remaining icons
 * are hand-drawn to match — mast cell, lysing cell, eosinophil, lymph node,
 * and the heart+stomach organ pairing — for concepts Healthicons doesn't
 * cover, or covers at a scale that doesn't survive a 15-20px render.
 * Vitamin B12 and ENT/Asthma use lucide-react's Atom and Wind directly
 * (wired in ContributionCards.tsx) rather than a custom drawing, since
 * those already fit and a hand-drawn equivalent would add nothing.
 */

export interface IconProps extends Omit<SVGProps<SVGSVGElement>, 'children'> {
  size?: number;
}

function Icon({ size = 20, children, ...rest }: IconProps & { children: ReactNode }) {
  return (
    <svg width={size} height={size} viewBox="0 0 48 48" fill="currentColor" aria-hidden="true" {...rest}>
      {children}
    </svg>
  );
}

/* A circle expressed as path data, so it can be concatenated into a single
   evenodd path — the only way to punch a true (background-colour-agnostic)
   hole in a solid fill, used for granules sitting inside a solid cell body. */
function circleD(cx: number, cy: number, r: number): string {
  return `M${cx + r} ${cy} A${r} ${r} 0 1 0 ${cx - r} ${cy} A${r} ${r} 0 1 0 ${cx + r} ${cy} Z`;
}
function punched(base: string, holes: [number, number, number][]): string {
  return [base, ...holes.map(([cx, cy, r]) => circleD(cx, cy, r))].join(' ');
}

