/** Lymph node in cross-section — capsule, cortical follicles, afferent
    vessels and an efferent vessel at the hilum. LN involvement (C).
    Hand-drawn: Healthicons' lymph-nodes draws the branching lymphatic chain
    rather than a single node, and collapses into an illegible tangle at the
    15px the workup tab renders it at. */
export const LymphNodeIcon = (p: IconProps) => (
  <Icon {...p}>
    <path d={LYMPH_NODE_D} />
    {LYMPH_NODE_VESSELS.map(([x1, y1, x2, y2, w]) => (
      <line key={`${x1}-${y1}`} x1={x1} y1={y1} x2={x2} y2={y2} stroke="currentColor" strokeWidth={w} strokeLinecap="round" />
    ))}
  </Icon>
);

